targets.query:
import "math"

from(bucket: "weather")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "weather" and r.sensor_type == "37" and (r._field == "wind_dir_last" or r._field == "wind_speed_last"))
  |> group()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.wind_dir_last and exists r.wind_speed_last)
  |> map(fn: (r) => ({u: r.wind_speed_last * math.sin(x: float(v: r.wind_dir_last) * math.pi / 180.0), v: r.wind_speed_last * math.cos(x: float(v: r.wind_dir_last) * math.pi / 180.0)}))
  |> reduce(identity: {u: 0.0, v: 0.0}, fn: (r, accumulator) => ({u: accumulator.u + r.u, v: accumulator.v + r.v}))
  |> map(fn: (r) => {
      d = math.atan2(y: r.u, x: r.v) * 180.0 / math.pi
      return {_value: if d < 0.0 then d + 360.0 else d}
  })

options.script:
const s = data.series[0];
const sectors = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const bins = [[0, 5, '0–5'], [5, 10, '5–10'], [10, 20, '10–20'], [20, 30, '20–30'], [30, 40, '30–40'], [40, Infinity, '40+']];
const colors = ['#D9C2EE', '#D3B8EC', '#B877D9', '#9A57C4', '#7A3FA5', '#552C7A'];
if (!s) return { data: [], layout: { annotations: [{ text: 'No data in range', showarrow: false }] } };
const col = (name, i) => (s.fields.find(f => f.name === name) || s.fields[i]).values;
const dir = col('dir', 2), spd = col('speed', 1);
const counts = bins.map(() => new Array(16).fill(0));
let n = 0;
for (let i = 0; i < dir.length; i++) {
  const d = dir[i], v = spd[i];
  if (d == null || v == null) continue;
  const sector = Math.round((((d % 360) + 360) % 360) / 22.5) % 16;
  const b = bins.findIndex(([lo, hi]) => v >= lo && v < hi);
  counts[b][sector]++;
  n++;
}
return {
  data: bins.map(([, , label], i) => ({
    type: 'barpolar', name: label + ' km/h', theta: sectors,
    r: counts[i].map(c => (n ? (100 * c) / n : 0)),
    marker: { color: colors[i], line: { width: 0 } },
    hovertemplate: '%{theta} · ' + label + ' km/h<br>%{r:.1f}% of readings<extra></extra>',
  })),
  layout: {
    polar: {
      bgcolor: 'rgba(0,0,0,0)', bargap: 0.06,
      angularaxis: { direction: 'clockwise', rotation: 90, tickfont: { size: 10 }, gridcolor: 'rgba(128,128,128,0.25)' },
      radialaxis: { ticksuffix: '%', angle: 90, tickangle: 90, tickfont: { size: 9 }, gridcolor: 'rgba(128,128,128,0.25)', showline: false },
    },
    showlegend: true,
    legend: { orientation: 'v', x: 1.02, y: 0.5, font: { size: 10 }, traceorder: 'reversed' },
    margin: { t: 24, b: 24, l: 24, r: 24 },
    paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)',
  },
  config: { displayModeBar: false, responsive: true },
};
